/* Game-local platform layout. Carriage and actor geometry stay source-owned. */
.pf-courtesy .app,.pf-courtesy .app.is-intro,.pf-courtesy .app.is-result,.pf-courtesy .app:not(.is-intro):not(.is-result){width:100%;max-width:min(980px,max(460px,calc((100dvh - 265px)*2.65 + 48px)));min-height:100dvh;height:auto;display:flex;flex-direction:column;justify-content:center;padding:16px 20px;gap:14px}
.pf-game.pf-courtesy .app .pf-header{margin:0;grid-template-columns:auto minmax(0,1fr) auto}
.pf-game.pf-courtesy .app .pf-header h1{transform:none;text-shadow:none}
.pf-game.pf-courtesy .app .pf-header .header-actions{grid-column:2;grid-row:2;justify-self:end;height:44px}
.pf-courtesy .app .header-actions .hud{display:flex}
.pf-courtesy .app.is-intro .header-actions,.pf-courtesy .app.is-result .header-actions{visibility:hidden}
.pf-courtesy .app .round-layout{display:block;width:100%;flex:none;min-height:0}
.pf-courtesy .app .game-wrap{width:100%;height:auto;max-height:none;min-height:0;padding-top:0;align-self:auto}
.pf-courtesy .app #game{width:100%;height:auto;aspect-ratio:var(--carriage-ratio);max-height:none}
.pf-courtesy .controls{width:100%;padding-top:0}
.pf-courtesy #intro,.pf-courtesy #pause-overlay{display:none!important}
.pf-courtesy #result{padding:22px;display:block;text-align:left}
.pf-courtesy #result .result-card{width:100%;max-width:none}
.pf-courtesy #result .rank{font-size:62px;flex-shrink:0}
.pf-courtesy #result .result-heading{align-items:center}
.pf-courtesy #result .start{width:100%;min-height:48px;margin:16px 0;font-size:20px}
.pf-courtesy #result-photo{display:block;width:100%;height:auto;margin-top:16px;border-radius:12px}
.pf-courtesy #share-preview{width:100%;height:auto;user-select:auto;-webkit-touch-callout:default}
.pf-courtesy #share-text{user-select:text;-webkit-user-select:text;touch-action:pan-y}
.pf-courtesy .platform-ranking-note,.pf-courtesy .share-note{font-size:14px!important;color:#526c5b;line-height:1.5}
.pf-courtesy .pf-entry .help-body{overflow:visible;padding:0;scrollbar-gutter:auto}
.pf-courtesy .pf-entry :is(button,input),.pf-courtesy #result button{touch-action:manipulation}
@media(max-width:650px){
 .pf-courtesy .app,.pf-courtesy .app.is-intro,.pf-courtesy .app.is-result,.pf-courtesy .app:not(.is-intro):not(.is-result){max-width:100%;padding:12px;gap:12px;justify-content:flex-start}
 .pf-game.pf-courtesy .app .pf-header{grid-template-columns:auto minmax(52px,1fr) auto;gap:4px 6px}
 .pf-game.pf-courtesy .app .pf-header>.pf-studio-heading{grid-column:1/-1;grid-row:2;padding-right:0}
 .pf-game.pf-courtesy .app .pf-header nav{grid-column:3;grid-row:1;display:flex;width:auto;gap:4px}
 .pf-game.pf-courtesy .app .pf-header nav button{width:auto;min-width:44px;padding:0 7px}
 .pf-game.pf-courtesy .app .pf-header .header-actions{grid-column:2;grid-row:1;justify-self:end}
 .pf-game.pf-courtesy .app .pf-header h1{font-size:20px;padding:0}
 .pf-game.pf-courtesy .app .pf-header .pf-studio-live{font-size:9px}
 .pf-courtesy .action{min-height:72px}.pf-courtesy .action b{font-size:19px}
 .pf-courtesy .status-row p{font-size:16px}
}
@media(min-width:651px){.pf-game.pf-courtesy .app .pf-header{grid-template-columns:auto minmax(0,1fr) auto auto}.pf-game.pf-courtesy .app .pf-header nav{grid-column:4;grid-row:1}.pf-game.pf-courtesy .app .pf-header .header-actions{grid-column:3;grid-row:1}}
@media(max-height:480px){.pf-courtesy .app{justify-content:flex-start}.pf-courtesy .pf-result-dialog{max-height:calc(100dvh - 24px)}}

/* Result is one compact desktop sheet, independent of the carriage canvas. */
.pf-courtesy #result{width:min(880px,calc(100vw - 24px - env(safe-area-inset-left) - env(safe-area-inset-right)));padding:16px 20px;overflow:auto}
.pf-courtesy #result .result-card{display:flex;flex-direction:column;gap:8px}
.pf-courtesy #result-photo{width:100%;height:auto;max-height:none;object-fit:contain;margin:0;border:1px solid #c8d4c5;background:#e9eddf;border-radius:12px}
.pf-courtesy #result .result-heading{gap:12px}
.pf-courtesy #result .rank{font-size:46px;line-height:1}
.pf-courtesy #result h2{font-size:26px;line-height:1.2;margin:0}
.pf-courtesy #result p{margin:0;font-size:14px;line-height:1.4}
.pf-courtesy #result .result-stats{margin:0;gap:20px}
.pf-courtesy #result .result-stats strong{font-size:26px}
.pf-courtesy #result .result-stats span{font-size:15px}
.pf-courtesy #result .result-remaining{font-size:17px;font-weight:800}
.pf-courtesy #result .pf-result-play{display:grid;grid-template-columns:1fr 1fr;margin:2px 0;gap:10px}
.pf-courtesy #result .pf-result-play button{width:100%;min-height:46px;margin:0;padding:8px 12px;font-size:17px}
.pf-courtesy #result-upload:empty{display:none}
.pf-courtesy #result-upload .pf-leaderboard{margin:0}
.pf-courtesy #result-upload .pf-leaderboard>summary{min-height:36px;padding:7px 10px;font-size:14px}
.pf-courtesy #result #share-status:empty{display:none}
.pf-courtesy #result .share-note,.pf-courtesy #result .pf-studio-result{font-size:11px;line-height:1.3}
.pf-courtesy #result .pf-studio-result{margin:0;padding:0}
/* Short viewports use the width for photo + summary, with actions below. */
@media(min-width:651px) and (max-height:600px){
 .pf-courtesy #result{width:min(980px,calc(100vw - 24px - env(safe-area-inset-left) - env(safe-area-inset-right)));padding:10px 16px}
 .pf-courtesy #result .result-card{display:grid;grid-template-columns:minmax(0,1.45fr) minmax(0,1fr);gap:4px 16px;align-items:center}
 .pf-courtesy #result-photo{grid-column:1;grid-row:1 / span 4;align-self:center}
 .pf-courtesy #result .result-card> :is(.result-heading,#result-comment,.result-stats,.result-remaining){grid-column:2}
 .pf-courtesy #result .result-card> :where(.pf-result-play,#result-upload,.pf-share-actions,#share-status,.share-note,.pf-studio-result){grid-column:1 / -1}
 .pf-courtesy #result .result-heading{gap:8px}
 .pf-courtesy #result .rank{font-size:38px;margin:0}
 .pf-courtesy #result h2{font-size:22px}
 .pf-courtesy #result .result-stats{flex-wrap:wrap;gap:4px 12px}
 .pf-courtesy #result .result-stats strong{font-size:23px}
 .pf-courtesy #result .result-stats span{font-size:13px}
 .pf-courtesy #result .result-remaining{font-size:15px}
 .pf-courtesy #result-upload .pf-leaderboard:not([open]){padding:0}
 .pf-courtesy #result-upload .pf-leaderboard>summary{min-height:44px;display:flex;align-items:center}
 .pf-courtesy #result .share-note{grid-column:1}
 .pf-courtesy #result .pf-studio-result{grid-column:2;text-align:right}
}
@media(max-width:650px){
 .pf-courtesy #result{width:calc(100vw - 24px - env(safe-area-inset-left) - env(safe-area-inset-right));padding:14px}
 .pf-courtesy #result-photo{height:auto;max-height:none}
 .pf-courtesy #result .pf-result-play button{font-size:16px}
 .pf-courtesy #result .result-stats{gap:10px 18px}
 .pf-courtesy #result .result-card{gap:10px}
}

/* Pointer/touch focus stays quiet; keyboard focus remains clearly visible. */
.pf-courtesy #result :is(button,a):focus:not(:focus-visible){outline:none}
.pf-courtesy #result :is(button,a):focus-visible{outline:3px solid #dc683e;outline-offset:2px}

@media(min-width:651px) and (max-height:480px){
 .pf-game.pf-courtesy .app .pf-header{grid-template-columns:auto minmax(52px,1fr) auto;gap:4px 6px}
 .pf-game.pf-courtesy .app .pf-header>.pf-studio-heading{grid-column:1 / -1;grid-row:2}
 .pf-game.pf-courtesy .app .pf-header nav{grid-column:3;grid-row:1}
 .pf-game.pf-courtesy .app .pf-header .header-actions{grid-column:2;grid-row:1}
}

@media(max-width:360px){
 .pf-game.pf-courtesy .app .pf-header nav button{padding:0 4px;font-size:12px}
}

import {createEntryShell} from '../shared/entry-shell.mjs';
import {syncPauseButton,createResultDialog} from '../shared/game-ui.mjs';
import {audioPreferences} from '../shared/audio-preferences.mjs';
import {mountLeaderboard} from '../shared/leaderboard.mjs';
import {recordPlayStart} from '../shared/play-counts.mjs';
import {copyResultFrame,createCourtesySharing} from './share.mjs';
const $=id=>document.getElementById(id),active=s=>['play','seating','depart'].includes(s.phase);
export function courtesyAudio(audio,music,prefs=audioPreferences()){
 const listeners=new Set();let last='';
 const note=audio.note.bind(audio),noise=audio.noise.bind(audio),startBuffer=music.startBuffer.bind(music);
 audio.note=(frequency,duration=.1,offset=0,type='triangle',volume=.045,end)=>note(frequency,duration,offset,type,volume*prefs.get().effectsVolume/.7,end);
 audio.noise=(duration=.16,volume=.07)=>noise(duration,volume*prefs.get().effectsVolume/.7);
 const volume=()=>{const v=prefs.get().musicVolume*.48;music.media.volume=v;if(music.gain)music.gain.gain.value=v;};
 music.startBuffer=(...args)=>{startBuffer(...args);volume();};
 function apply(){const p=prefs.get();audio.enabled=p.effectsEnabled;music.setEnabled(p.musicEnabled);volume();emit();}
 const getState=()=>{const p=prefs.get();return{...p,musicPlaying:!music.audio.paused,musicStatus:music.blocked?'error':music.loading?'loading':music.buffer?'ready':'locked',effectsStatus:audio.context?.state==='running'?'ready':'locked',suspended:music.pausedByGame,message:'聲音暫時無法播放，點擊音樂按鈕可重試。'};};
 function emit(){const next=JSON.stringify(getState());if(next!==last){last=next;for(const fn of listeners)fn();}}
 prefs.subscribe(apply);apply();
 return{getState,subscribe(fn){listeners.add(fn);return()=>listeners.delete(fn);},sync:emit,unlock(){audio.unlock();return music.play();},setMusicEnabled:musicEnabled=>prefs.set({musicEnabled}),setEffectsEnabled:effectsEnabled=>prefs.set({effectsEnabled}),setMusicVolume:musicVolume=>prefs.set({musicVolume}),setEffectsVolume:effectsVolume=>prefs.set({effectsVolume})};
}
export function installCourtesyPlatform(scene,audio,music){
 const sharing=createCourtesySharing(document),result=createResultDialog($('result'),{focusTarget:()=>$('restart'),returnFocus:()=>$('toolbar-restart')});
 const advanced=$('instructions').querySelector('.help-body');advanced.removeAttribute('tabindex');
 const entry=createEntryShell({document,title:'客氣大賽',goal:'30 秒內和對方客氣互讓，次數越多越好；發車前有效按下謝謝就確認成功並記錄時間，沒按會跌倒！',operations:['←／你請坐：相同站立互讓姿勢，完成才計次。','→／謝謝：有效按下即確認成功；0.3 秒坐下動畫不影響成績。','點搶座乘客／空白鍵趕人；倒數 30→20 後隱藏。'],advanced,canStart:()=>scene.ready,onStart:()=>scene.start(),onHelpEnter:()=>{if(active(scene)&&!scene.tabPaused)scene.pauseRound();}});
 const originalStart=scene.start.bind(scene),originalPause=scene.pauseRound.bind(scene),originalResume=scene.resumeRound.bind(scene);
 let captureSerial=0;
 scene.start=()=>{if(document.hidden||scene.starting)return;captureSerial++;sharing.reset();leaderboard?.reset();result.close();entry.close({restoreView:false});if(scene.tabPaused){scene.tabPaused=false;scene.scene.resume();$('pause-overlay').classList.add('hidden');}originalStart();sync();};
 scene.pauseRound=()=>{originalPause();if(scene.tabPaused){$('pause-overlay').classList.add('hidden');entry.openPause();entry.dialog.querySelector('[data-pf-pause]')?.append(help);}sync();};
 scene.resumeRound=()=>{if(document.hidden)return;entry.close({restoreView:false});originalResume();sync();};
 entry.configurePause({canContinue:()=>!document.hidden,onContinue:()=>scene.resumeRound(),onRestart:()=>scene.start()});
 const audioAdapter=courtesyAudio(audio,music);entry.setAudio(audioAdapter);
 document.querySelector('[data-pf-music-toggle]')?.setAttribute('data-game-action','music');$('sound').removeAttribute('data-game-action');
 const leaderboard=mountLeaderboard({document,game:'courtesy-contest',entry:entry.dialog,result:$('result'),resultActionContainer:$('result-play'),resultUploadContainer:$('result-upload'),shell:entry});
 const help=document.createElement('button');help.className='pf-menu-row';help.textContent='操作說明與素材授權';help.onclick=()=>entry.open({help:true});entry.dialog.addEventListener('click',()=>{const root=entry.dialog.querySelector('[data-pf-pause]');if(root&&!root.contains(help))root.append(help);});
 $('toolbar-restart').onclick=()=>scene.start();$('toolbar-pause').onclick=()=>scene.tabPaused?scene.resumeRound():scene.pauseRound();$('restart').onclick=()=>scene.start();$('resume').onclick=()=>scene.resumeRound();
 window.addEventListener('blur',()=>scene.pauseRound());
 document.addEventListener('visibilitychange',()=>{if(!document.hidden&&scene.tabPaused){const resume=entry.dialog.querySelector('[data-pf-continue]');if(resume)resume.disabled=false;}});
 window.addEventListener('keydown',e=>{if(e.target?.closest?.('input,textarea,select,[contenteditable],dialog'))return;if(['p','P','Escape'].includes(e.key)&&active(scene)){e.preventDefault();scene.tabPaused?scene.resumeRound():scene.pauseRound();}});
 $('intro').hidden=true;$('intro').classList.add('hidden');document.querySelector('[data-pf-entry-loading]')?.remove();entry.open();sync();
 function sync(){syncPauseButton($('toolbar-pause'),{paused:scene.tabPaused,available:active(scene)});$('toolbar-restart').disabled=!scene.ready||scene.starting;audioAdapter.sync();}
 return{sync,started(){captureSerial++;sharing.reset();leaderboard?.reset();result.close();recordPlayStart(window,'courtesy-contest');sync();},finished(){
  sync();leaderboard?.setResult({phase:'done',seated:scene.seated===true,count:scene.count,remaining:Number.isFinite(scene.seatAcceptedAtMs)?Math.ceil((30000-scene.seatAcceptedAtMs)/10)/100:null});const token=++captureSerial,data={grade:$('rank').textContent,title:$('result-title').textContent,count:scene.count,bonus:scene.chainBonus,status:$('result-status-text').textContent,remaining:$('result-remaining').textContent};
  // Keep the stage geometry unchanged. Snapshot its actual final rendered pose.
  const capture=()=>{if(token!==captureSerial||scene.phase!=='result')return;try{sharing.prepare(copyResultFrame(document,scene.game.canvas),data);}catch{$('share-status').textContent='成績圖片暫時無法產生。';}result.open();};
  scene.game.events.once('postrender',capture);
 }};
}
let controller;
window.courtesyPlatform={ready(scene,audio,music){controller=installCourtesyPlatform(scene,audio,music);},started(){controller?.started();},finished(){controller?.finished();},sync(){controller?.sync();}};

// Same measured typography, colors and 1080×1180 output as the platform athletics cards.
// The photo is the frozen, complete final game frame, never a replacement illustration.
export function paintCourtesyScoreCard(source,info,createCanvas=()=>document.createElement('canvas')){
 if(!source.width||!source.height)throw Error('Game screenshot is not ready');
 const canvas=createCanvas();canvas.width=1080;canvas.height=1180;const ctx=canvas.getContext('2d');if(!ctx)throw Error('Image canvas unavailable');
 ctx.fillStyle='#f4f1e9';ctx.fillRect(0,0,1080,1180);
 const x=44,width=992,gap=14;let cursor=30;
 function metrics(value,size){const m=ctx.measureText(value);return{width:m.width,ascent:m.actualBoundingBoxAscent??size*.85,descent:m.actualBoundingBoxDescent??size*.25};}
 function block(value,size,color='#172c3b',weight=700,maxLines=1){
  value=String(value??'');const set=()=>{ctx.font=`${weight} ${size}px system-ui, sans-serif`;};set();
  if(maxLines===1)while(size>16&&metrics(value,size).width>width){size--;set();}
  let lines=[],line='';for(const char of value){if(line&&metrics(line+char,size).width>width){lines.push(line);line=char;}else line+=char;}if(line)lines.push(line);
  if(lines.length>maxLines){lines=lines.slice(0,maxLines);let last=lines.at(-1);while(last&&metrics(last+'…',size).width>width)last=last.slice(0,-1);lines[lines.length-1]=last+'…';}
  const measured=lines.map(text=>({text,...metrics(text,size)}));
  return{height:measured.reduce((sum,m)=>sum+m.ascent+m.descent,0)+Math.max(0,measured.length-1)*10,draw(top){set();ctx.fillStyle=color;let y=top;for(const m of measured){ctx.fillText(m.text,x,y+m.ascent);y+=m.ascent+m.descent+10;}}};
 }
 function place(b){b.draw(cursor);cursor+=b.height+gap;}
 place(block('PLAYFORMOSA STUDIO',27,'#607461'));
 place(block('客氣大賽',52));
 place(block('本次互讓成績',24,'#607461'));
 place(block(info.count+' 次互讓',126,'#172c3b',900));
 place(block(info.grade+' · '+info.title,29,'#536954',700,2));
 place(block(info.status+(info.bonus?' · 連鎖 +'+info.bonus:''),27,'#536954'));
 place(block(info.remaining,27,'#536954'));
 const footer=[block('島遊無界 · PLAYFORMOSA',29,'#607461'),block('客氣大賽',22,'#7e8a80',500)];
 const footerHeight=footer.reduce((sum,b)=>sum+b.height+gap,0),h=Math.floor(Math.min(588,canvas.height-30-cursor-gap-footerHeight));
 const scale=Math.min(width/source.width,h/source.height);
 ctx.fillStyle='#beded1';ctx.fillRect(x,cursor,width,h);
 ctx.drawImage(source,x+(width-source.width*scale)/2,cursor+(h-source.height*scale)/2,source.width*scale,source.height*scale);
 ctx.strokeStyle='#d3dacb';ctx.lineWidth=2;ctx.strokeRect?.(x,cursor,width,h);cursor+=h+gap;
 footer.forEach(place);return canvas;
}

import test from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import * as p from './helpers/courtesy-result-mobile-provenance.mjs';
const read=path=>readFileSync(new URL('../'+path,import.meta.url));
test('result/mobile reconstructs its complete remote parent and rejects invented history',()=>{
 assert.equal(p.verifyCourtesyResultMobileBase(p.courtesyResultMobileBaseline),true);
 assert.equal(p.courtesyResultMobileBaseline.files.length,1538);
 for(const mutate of [b=>b.baseCommit='0'.repeat(40),b=>b.baseTree='0'.repeat(40),b=>b.files.pop(),b=>b.files.push(b.files[0]),b=>b.files[0].gitBlob='0'.repeat(40)]){const b=structuredClone(p.courtesyResultMobileBaseline);mutate(b);assert.throws(()=>p.verifyCourtesyResultMobileBase(b));}
});
test('every authorized changed byte restores its independently pinned preimage and rejects drift',()=>{
 const m=p.courtesyResultMobileManifest();
 for(const f of m.files){const live=read(f.path),before=p.reverseCourtesyResultMobile(f.path,live);assert.equal(p.gitBlob(before),f.beforeGitBlob);assert.deepEqual(p.courtesyResultMobileParentBytes(f.path,before),before);assert.throws(()=>p.reverseCourtesyResultMobile(f.path,Buffer.concat([live,Buffer.from('drift')])));
  const forged=structuredClone(m),row=forged.files.find(x=>x.path===f.path);row.beforeGitBlob='0'.repeat(40);assert.throws(()=>p.reverseCourtesyResultMobile(f.path,live,forged));
 }
 const forged=structuredClone(m);forged.files[0].beforeText='forged preimage';forged.files[0].beforeGitBlob=p.gitBlob(Buffer.from(forged.files[0].beforeText));forged.files[0].beforeSha256=p.sha256(Buffer.from(forged.files[0].beforeText));assert.throws(()=>p.validateCourtesyResultMobileManifest(forged));
});
test('additions are exact, hashed, nonhistorical and leave unknown paths visible',()=>{
 const before=p.courtesyResultMobileBaseline.files.map(f=>f.path),current=[...before,...p.COURTESY_RESULT_MOBILE_ADDED];
 assert.deepEqual(p.inventoryBeforeCourtesyResultMobile(current),before);
 for(const path of p.COURTESY_RESULT_MOBILE_ADDED){assert.throws(()=>p.inventoryBeforeCourtesyResultMobile(current.filter(x=>x!==path)));assert.throws(()=>p.reverseCourtesyResultMobile(path,read(path)));}
 for(const f of p.courtesyResultMobileManifest().addedFiles)assert.throws(()=>p.inventoryBeforeCourtesyResultMobile(current,{read:path=>path===f.path?Buffer.from('drift'):read(path)}));
 assert.throws(()=>p.inventoryBeforeCourtesyResultMobile([...current,current[0]]));
 assert.ok(p.inventoryBeforeCourtesyResultMobile([...current,'public/unknown.mjs']).includes('public/unknown.mjs'));
 assert.deepEqual(p.inventoryBeforeCourtesyResultMobile(['public/old-only.mjs']),['public/old-only.mjs']);
});
test('historical manifests, database schemas, gameplay and other materialized source retain parent bytes',()=>{
 const missing=[];
 for(const f of p.courtesyResultMobileBaseline.files){let live;try{live=read(f.path);}catch(e){if(e.code!=='ENOENT')throw e;missing.push(f.path);continue;}
  assert.equal(p.gitBlob(p.reverseCourtesyResultMobile(f.path,live)),f.gitBlob,f.path);
  if(!p.COURTESY_RESULT_MOBILE_CHANGED.includes(f.path))assert.equal(p.gitBlob(live),f.gitBlob,f.path+' unchanged outside the exact follow-up scope');
 }
 // A complete checkout has no omissions; a sparse local snapshot may lack only this pinned legacy binary.
 if(missing.length)assert.deepEqual(missing,['docs/fast-hands/baselines/screen-alpha/assets/duel-items-atlas.png']);
});

import test from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {JSDOM} from 'jsdom';
const read=p=>readFileSync(new URL('../'+p,import.meta.url),'utf8');
test('courtesy uses the existing platform loading screen and recoverable bootstrap',()=>{
 const d=new JSDOM(read('public/games/courtesy-contest/index.html')).window.document;
 const platform=new JSDOM(read('public/games/high-jump/index.html')).window.document;
 assert.equal(d.documentElement.dataset.pfStartup,'pending');
 d.querySelector('.pf-loading-joke').textContent=platform.querySelector('.pf-loading-joke').textContent;
 for(const id of ['pf-startup-style','pf-startup-script','pf-startup'])assert.equal(d.getElementById(id)?.outerHTML,platform.getElementById(id).outerHTML,id);
 const preloads=[...d.querySelectorAll('link[rel=modulepreload]')].map(n=>n.getAttribute('href'));
 for(const s of d.querySelectorAll('script[type=module][src]'))assert.ok(preloads.includes(s.getAttribute('src')));
 assert.match(read('public/games/courtesy-contest/index.html'),/座位準備好了，客氣還在排隊。/);
 assert.ok(d.querySelector('#pf-startup a[href="/"]'));assert.ok(d.querySelector('#pf-startup a[href=""]'));
});
test('result photo leads the compact desktop result, with ranking outside sharing',()=>{
 const d=new JSDOM(read('public/games/courtesy-contest/index.html')).window.document;
 assert.equal(d.querySelector('#result .result-card').firstElementChild.id,'result-photo');
 assert.ok(d.querySelector('#result-play #restart'));assert.ok(d.querySelector('#result-upload'));
 assert.equal(d.querySelectorAll('.pf-share-actions [data-share]').length,3);
 assert.doesNotMatch(d.querySelector('#result').textContent,/排行榜尚未開放/);
 const css=read('public/games/courtesy-contest/platform.css');
 assert.match(css,/#result-photo[^}]*object-fit:contain/);
 assert.match(css,/#result[^}]*overflow:auto/);
